#!/usr/bin/env sh

# чистим избыточные локализации
i18n=./card.io/src/main/java/io/card/payment/i18n/locales

for entry in $i18n/*
do
    locale=${entry: -7}
    if [[ $locale != "RU.java" &&  $locale != "EN.java" ]]; then
        rm ${entry}
    fi
done

# пересоздаём LocalizedStringsList.java
tee $i18n/LocalizedStringsList.java > /dev/null <<EOT
package io.card.payment.i18n.locales;

import java.util.ArrayList;
import java.util.List;

import io.card.payment.i18n.StringKey;
import io.card.payment.i18n.SupportedLocale;

// Class autogenerated!  Do not modify.

public class LocalizedStringsList {
    public static final List<SupportedLocale<StringKey>> ALL_LOCALES = new ArrayList<>();

    static {
        ALL_LOCALES.add(new LocalizedStringsEN());
        ALL_LOCALES.add(new LocalizedStringsRU());
    }
}
EOT